#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef pair<ld,ld> pdd;
typedef complex<ld> pt;
typedef vector<pt> pol;
typedef vector<int> vi;

const char nl = '\n';
const ll INF = 0x3f3f3f3f;
const ll INFLL = 0x3f3f3f3f3f3f3f3f;
const ll MOD = 1e9+7;
const ld EPS = 1e-10;
mt19937 rng(chrono::high_resolution_clock::now().time_since_epoch().count());

const int T = 99;
const int C = 12;

struct Edge {
    int v, r;
    ll f, c, p;
};

const int MAX_NODES = 50 * T + 2;
vector<Edge> adj[MAX_NODES];
int sz[MAX_NODES];
ll mc;

void init_graph(int n = MAX_NODES) {
    mc = 0;
    fill(sz, sz + n, 0);
    fill(adj, adj + n, vector<Edge>());
}

void add_edge(int a, int b, ll c = 1, ll p = 0) {
    mc = max(mc, c);
    adj[a].emplace_back(Edge{b, sz[b]++, 0, c, p});
    adj[b].emplace_back(Edge{a, sz[a]++, 0, 0, -p});
}

bool vis[MAX_NODES];
int par[MAX_NODES];
ll pot[MAX_NODES], dist[MAX_NODES];

void potential_init(int n) {
    fill(pot, pot + n, 0);
    for (int i = 1; i < n; i++) {
        for (int u = 0; u < n; u++) {
            for (const Edge& e : adj[u]) {
                if (e.c) {
                    pot[e.v] = min(pot[e.v], pot[u] + e.p);
                }
            }
        }
    }
}

ll min_cost_augment(int s, int t, ll& price, int n, bool sparse) {
    fill(vis, vis + n, false);
    fill(dist, dist + n, INF);
    dist[s] = 0;

    if (sparse) {
        priority_queue<pair<ll, int>> dk;
        dk.push({0, s});
        while (!dk.empty()) {
            int u = dk.top().second;
            dk.pop();
            if (vis[u]) continue;
            for (const Edge& e : adj[u]) {
                if (e.f < e.c && dist[e.v] > dist[u] + pot[u] - pot[e.v] + e.p) {
                    dist[e.v] = dist[u] + pot[u] - pot[e.v] + e.p;
                    par[e.v] = e.r;
                    dk.push({-dist[e.v], e.v});
                }
            }
        }
    } else {
        for (int u = s; u != -1; ) {
            vis[u] = true;
            for (const Edge& e : adj[u]) {
                if (e.f < e.c && dist[e.v] > dist[u] + pot[u] - pot[e.v] + e.p) {
                    dist[e.v] = dist[u] + pot[u] - pot[e.v] + e.p;
                    par[e.v] = e.r;
                }
            }
            u = -1;
            ll best = INF;
            for (int i = 0; i < n; i++) {
                if (!vis[i] && dist[i] < best) {
                    best = dist[u = i];
                }
            }
        }
    }

    if (dist[t] >= INF) {
        return 0;
    }

    ll df = INF;
    for (int u = t; u != s; ) {
        const Edge& r = adj[u][par[u]];
        df = min(df, adj[r.v][r.r].c - adj[r.v][r.r].f);
        u = r.v;
    }

    for (int u = t; u != s; ) {
        Edge& r = adj[u][par[u]];
        Edge& e = adj[r.v][r.r];
        e.f += df;
        r.f -= df;
        price += df * e.p;
        u = r.v;
    }

    for (int i = 0; i < n; i++) {
        pot[i] = min(INF, dist[i] + pot[i]);
    }

    return df;
}

ll min_cost_flow(int s, int t, ll& price, int n = MAX_NODES, bool sparse = false) {
    ll flow = 0;
    price = 0;
    while (ll df = min_cost_augment(s, t, price, n, sparse)) {
        flow += df;
    }
    return flow;
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    cout << fixed << setprecision(10);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int source = 0;
    const int sink = n * T + 1;

    for (int i = 0; i < k; i++) {
        int a;
        cin >> a;
        add_edge(source, a, 1, 0);
    }

    for (int t = 0; t < T; t++) {
        add_edge(1 + t * n, sink, INF, 0);
        if (t > 0) {
            for (int i = 1; i <= n; i++) {
                add_edge(i + (t - 1) * n, i + t * n, INF, c);
            }
        }
    }

    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        for (int j = 0; j < C; j++) {
            int cost = (j + 1) * (j + 1) - j * j;
            for (int t = 1; t < T; t++) {
                add_edge(a + (t - 1) * n, b + t * n, 1, cost * d + c);
                add_edge(b + (t - 1) * n, a + t * n, 1, cost * d + c);
            }
        }
    }

    ll price, flow = min_cost_flow(source, sink, price, sink + 1, true);
    assert(flow == k);
    cout << price << nl;

    return 0;
}
